class Entry:
    """Tek bir ceviri girisi."""

    def __init__(self, msgid: str, msgstr: str = "",
                 context: Optional[str] = None,
                 plural: Optional[str] = None,
                 plurals: Optional[List[str]] = None,
                 comments: Optional[List[str]] = None,
                 references: Optional[List[str]] = None,
                 fuzzy: bool = False, obsolete: bool = False):
        self.msgid = msgid
        self.msgstr = msgstr
        self.context = context
        self.plural = plural                    # msgid_plural
        self.plurals = plurals or []            # msgstr[0], msgstr[1], ...
        self.comments = comments or []          # "#." ile yazilan aciklamalar
        self.references = references or []      # "#:" kaynak konumlari
        self.fuzzy = fuzzy
        self.obsolete = obsolete

    @property
    def key(self) -> Key:
        return (self.context, self.msgid)

    @property
    def translated(self) -> bool:
        """Kullanilabilir bir cevirisi var mi? (fuzzy **sayilmaz**)"""
        if self.fuzzy or self.obsolete:
            return False
        if self.plural is not None:
            return any(self.plurals)
        return bool(self.msgstr)

    def __repr__(self) -> str:
        return f"<Entry {self.msgid[:30]!r} fuzzy={self.fuzzy}>"


class Catalog:
    """Bir `.po` dosyasinin tamami: basligi ve girisleri."""

    def __init__(self, entries: Optional[List[Entry]] = None,
                 headers: Optional[Dict[str, str]] = None):
        self.entries: List[Entry] = entries or []
        self.headers: Dict[str, str] = headers or {}

    # -- arama ------------------------------------------------------------
    def by_key(self) -> Dict[Key, Entry]:
        return {e.key: e for e in self.entries if not e.obsolete}

    @property
    def plural_forms(self) -> str:
        return self.headers.get("Plural-Forms", "")

    # -- sayim ------------------------------------------------------------
    def counts(self) -> Dict[str, int]:
        live = [e for e in self.entries if not e.obsolete]
        return {
            "toplam": len(live),
            "cevrili": sum(1 for e in live if e.translated),
            "fuzzy": sum(1 for e in live if e.fuzzy),
            "bos": sum(1 for e in live if not e.translated and not e.fuzzy),
            "bayat": sum(1 for e in self.entries if e.obsolete),
        }


# --------------------------------------------------------------------------
# Okuma
# --------------------------------------------------------------------------
def load(code: str) -> po.Catalog:
    try:
        with open(catalog_path(code), "r", encoding="utf-8") as fh:
            return po.parse(fh.read())
    except FileNotFoundError:
        basliklar = dict(VARSAYILAN_BASLIK)
        basliklar["Language"] = code
        return po.Catalog(headers=basliklar)


def save(code: str, catalog: po.Catalog) -> None:
    os.makedirs(CATALOGS, exist_ok=True)
    with open(catalog_path(code), "w", encoding="utf-8", newline="\n") as fh:
        fh.write(po.dump(catalog))


def nplurals(catalog: po.Catalog) -> int:
    match = re.search(r"nplurals\s*=\s*(\d+)", catalog.plural_forms or "")
    return int(match.group(1)) if match else 2


def refresh(code: str) -> dict:
    """Sozlugu kaynaga gore tazeler (`msgmerge` esdegeri).

    Ceviriler korunur; kaynakta kalmayan giris **silinmez**, bayatlatilir;
    benzer yeni bir giris varsa cevirisi oraya tasinip `fuzzy` isaretlenir.
    """
    catalog = load(code)
    if not catalog.headers:
        catalog.headers = dict(VARSAYILAN_BASLIK, Language=code)
    catalog.headers.setdefault("Language", code)
    sayac = po.merge(catalog, collect_entries())
    save(code, catalog)
    sayac.update(catalog.counts())
    return sayac


